#include <algorithm>
#include <cctype>
#include <functional>
#include <map>
#include <string>
#include <vector>

class Console
{
public:
    using Command = std::function<std::string(const std::vector<std::string>&)>;

    void addCommand(const std::string& name, Command run) { m_commands[lower(name)] = std::move(run); }

    std::string execute(const std::string& line)
    {
        m_pos = -1;
        const std::vector<std::string> words{ split(line) };
        if (words.empty()) return "";
        m_log.push_back("> " + line);
        if (m_history.empty() || m_history.back() != line) m_history.push_back(line);
        const std::string name{ lower(words[0]) };
        std::string result;
        if (name == "help")
        {
            std::vector<std::string> names{ "help" };
            for (const auto& [n, c] : m_commands) names.push_back(n);
            std::sort(names.begin(), names.end());
            for (std::size_t i{ 0 }; i < names.size(); ++i) result += (i ? ", " : "") + names[i];
        }
        else
        {
            const auto it{ m_commands.find(name) };
            if (it == m_commands.end()) result = "Unknown command: " + words[0];
            else result = it->second(std::vector<std::string>(words.begin() + 1, words.end()));
        }
        if (!result.empty()) m_log.push_back(result);
        return result;
    }

    std::string historyUp(const std::string& current)
    {
        if (m_history.empty()) return current;
        if (m_pos == -1) { m_draft = current; m_pos = static_cast<int>(m_history.size()) - 1; }
        else if (m_pos > 0) --m_pos;
        return m_history[static_cast<std::size_t>(m_pos)];
    }

    std::string historyDown(const std::string& current)
    {
        if (m_pos == -1) return current;
        if (m_pos + 1 < static_cast<int>(m_history.size())) return m_history[static_cast<std::size_t>(++m_pos)];
        m_pos = -1;
        return m_draft;
    }

    std::string complete(const std::string& current)
    {
        if (current.find(' ') != std::string::npos) return current;
        const std::string typed{ lower(current) };
        std::vector<std::string> candidates;
        std::vector<std::string> names{ "help" };
        for (const auto& [n, c] : m_commands) names.push_back(n);
        for (const std::string& n : names) if (n.rfind(typed, 0) == 0) candidates.push_back(n);
        std::sort(candidates.begin(), candidates.end());
        if (candidates.empty()) return current;
        if (candidates.size() == 1) return candidates[0] + " ";
        std::string prefix{ candidates[0] };
        for (const std::string& c : candidates)
        {
            std::size_t n{ 0 };
            while (n < prefix.size() && n < c.size() && prefix[n] == c[n]) ++n;
            prefix.resize(n);
        }
        std::string line;
        for (std::size_t i{ 0 }; i < candidates.size(); ++i) line += (i ? "  " : "") + candidates[i];
        m_log.push_back(line);
        return prefix.size() > typed.size() ? prefix : current;
    }

    const std::vector<std::string>& log() const { return m_log; }

private:
    static std::string lower(std::string s)
    {
        for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        return s;
    }

    static std::vector<std::string> split(const std::string& line)
    {
        std::vector<std::string> words;
        std::string word;
        bool inQuotes{ false }, has{ false };
        for (char c : line)
        {
            if (c == '"') { inQuotes = !inQuotes; has = true; continue; }
            if (c == ' ' && !inQuotes) { if (has) words.push_back(word); word.clear(); has = false; continue; }
            word += c;
            has = true;
        }
        if (has) words.push_back(word);
        return words;
    }

    std::map<std::string, Command> m_commands;
    std::vector<std::string> m_log;
    std::vector<std::string> m_history;
    int m_pos{ -1 };
    std::string m_draft;
};

