Console makeConsole() {
    Console c;
    c.addCommand("god", [](const std::vector<std::string>&) { return std::string("god mode on"); });
    c.addCommand("give", [](const std::vector<std::string>& a) { return a.size() == 2 ? "gave " + a[1] + " " + a[0] : std::string("usage: give <item> <amount>"); });
    c.addCommand("say", [](const std::vector<std::string>& a) { return a.empty() ? std::string("") : a[0]; });
    c.addCommand("teleport", [](const std::vector<std::string>&) { return std::string("whoosh"); });
    c.addCommand("teleportall", [](const std::vector<std::string>&) { return std::string("whoosh x10"); });
    return c;
}
TEST("run commands") { Console c = makeConsole(); CHECK_EQ(c.execute("GOD"), std::string("god mode on")); CHECK_EQ(c.execute("give gold 500"), std::string("gave 500 gold")); CHECK_EQ(c.execute("nope 1"), std::string("Unknown command: nope")); }
TEST("quotes") { Console c = makeConsole(); CHECK_EQ(c.execute("say \"hello there\""), std::string("hello there")); CHECK_EQ(c.execute("say \"\""), std::string("")); }
TEST("the log") { Console c = makeConsole(); c.execute("god"); c.execute("  "); c.execute("say \"\""); CHECK_EQ(c.log(), (std::vector<std::string>{ "> god", "god mode on", "> say \"\"" })); }
TEST("help") { Console c = makeConsole(); CHECK_EQ(c.execute("help"), std::string("give, god, help, say, teleport, teleportall")); }
TEST("history") {
    Console c = makeConsole(); c.execute("god"); c.execute("give gold 1"); c.execute("give gold 1"); c.execute("say hi");
    CHECK_EQ(c.historyUp("typing"), std::string("say hi")); CHECK_EQ(c.historyUp("say hi"), std::string("give gold 1")); CHECK_EQ(c.historyUp("x"), std::string("god")); CHECK_EQ(c.historyUp("x"), std::string("god"));
    CHECK_EQ(c.historyDown("x"), std::string("give gold 1")); CHECK_EQ(c.historyDown("x"), std::string("say hi")); CHECK_EQ(c.historyDown("x"), std::string("typing")); CHECK_EQ(c.historyDown("typing"), std::string("typing"));
}
TEST("history is empty at first") { Console c = makeConsole(); CHECK_EQ(c.historyUp("abc"), std::string("abc")); CHECK_EQ(c.historyDown("abc"), std::string("abc")); }
TEST("complete one") { Console c = makeConsole(); CHECK_EQ(c.complete("gi"), std::string("give ")); CHECK_EQ(c.complete("HE"), std::string("help ")); }
TEST("complete several") { Console c = makeConsole(); CHECK_EQ(c.complete("tel"), std::string("teleport")); CHECK_EQ(c.log().back(), std::string("teleport  teleportall")); CHECK_EQ(c.complete("g"), std::string("g")); CHECK_EQ(c.log().back(), std::string("give  god")); }
TEST("complete none") { Console c = makeConsole(); CHECK_EQ(c.complete("zz"), std::string("zz")); CHECK_EQ(c.complete("give go"), std::string("give go")); }

